CREATE OR ALTER PROCEDURE [dbo].[uspContainerReturn_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @DeliveryOrderId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @CustomerId UNIQUEIDENTIFIER = NULL
	, @ReturnDate DATETIME = NULL
	, @ExpectedQuantity INT = NULL
	, @ReturnedQuantity INT = NULL
	, @DamagedQuantity INT = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[DeliveryOrderId]
			, j1.[DeliveryNo] AS [DeliveryOrderName]
			, t.[ReturnDate]
			, t.[Quantity]
			, t.[Status]
			, t.[Note]
			, t.[CustomerId]
			, j2.[DisplayName] AS [CustomerName]
			, t.[ExpectedQuantity]
			, t.[ReturnedQuantity]
			, t.[DamagedQuantity]
			, t.[CreatedDate]
		FROM [dbo].[ContainerReturn] AS t
		LEFT JOIN [dbo].[DeliveryOrder] AS j1 ON j1.[Id] = t.[DeliveryOrderId]
		LEFT JOIN [dbo].[Customer] AS j2 ON j2.[Id] = t.[CustomerId]
		WHERE 1 = 1
			AND (@DeliveryOrderId IS NULL OR t.[DeliveryOrderId] = @DeliveryOrderId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@CustomerId IS NULL OR t.[CustomerId] = @CustomerId)
			AND (@ReturnDate IS NULL OR t.[ReturnDate] = @ReturnDate)
			AND (@ExpectedQuantity IS NULL OR t.[ExpectedQuantity] = @ExpectedQuantity)
			AND (@ReturnedQuantity IS NULL OR t.[ReturnedQuantity] = @ReturnedQuantity)
			AND (@DamagedQuantity IS NULL OR t.[DamagedQuantity] = @DamagedQuantity)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryOrderId' THEN r.[DeliveryOrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryOrderId' THEN r.[DeliveryOrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryOrderName' THEN r.[DeliveryOrderName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryOrderName' THEN r.[DeliveryOrderName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'returnDate' THEN r.[ReturnDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'returnDate' THEN r.[ReturnDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'quantity' THEN r.[Quantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'quantity' THEN r.[Quantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerId' THEN r.[CustomerId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerId' THEN r.[CustomerId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerName' THEN r.[CustomerName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerName' THEN r.[CustomerName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'expectedQuantity' THEN r.[ExpectedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'expectedQuantity' THEN r.[ExpectedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'returnedQuantity' THEN r.[ReturnedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'returnedQuantity' THEN r.[ReturnedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'damagedQuantity' THEN r.[DamagedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'damagedQuantity' THEN r.[DamagedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
